// Filtrar vendas dos últimos 7 dias
const hoje = new Date();
const seteDiasAtras = new Date(hoje);
seteDiasAtras.setDate(hoje.getDate() - 7);

const vendasFiltradas = [];

for (const item of $input.all()) {
  const dataVenda = new Date(item.json['Data do Pedido']);

  if (dataVenda >= seteDiasAtras && item.json['Status do Pedido'] === 'Concluído') {
    vendasFiltradas.push({
      produto: item.json['Produto'],
      quantidade: parseInt(item.json['Quantidade Vendida']),
      valor: parseFloat(item.json['Valor Unitário']),
      data: item.json['Data do Pedido']
    });
  }
}

// Agrupar vendas por produto
const vendasPorProduto = {};
vendasFiltradas.forEach(venda => {
  if (!vendasPorProduto[venda.produto]) {
    vendasPorProduto[venda.produto] = {
      produto: venda.produto,
      quantidadeTotal: 0,
      valor: venda.valor,
      aparicoes: []
    };
  }
  vendasPorProduto[venda.produto].quantidadeTotal += venda.quantidade;
  vendasPorProduto[venda.produto].aparicoes.push(venda.data);
});

// Filtrar produtos com mais de 5 vendas
const produtosRelevantes = Object.values(vendasPorProduto)
  .filter(p => p.quantidadeTotal >= 5)
  .sort((a, b) => b.quantidadeTotal - a.quantidadeTotal);

return produtosRelevantes.map(p => ({ json: p }));

