const combos = $json.combos || [];
const mensagens = [];

combos.forEach((combo, index) => {
  const mensagem = `📊 *Sugestão de Combo Novo!*

Nome: ${combo.nome}
Itens: ${combo.itens.join(', ')}
Preço original: R$ ${combo.precoOriginal.toFixed(2)}
Preço sugerido: R$ ${combo.precoCombo.toFixed(2)}
Motivo: ${combo.justificativa}

Deseja cadastrar este combo no sistema? ✅`;

  mensagens.push({
    json: {
      mensagem: mensagem,
      combo: combo,
      dataHora: new Date().toISOString()
    }
  });
});

return mensagens;
